// ---------------------------------------------------------------------
// Edit this node before each run: the post content and the account IDs.
// (In production you would replace the Manual Trigger with a Form,
// Airtable row, or webhook and read these fields from the trigger.)
// ---------------------------------------------------------------------

// 1. The content
const text = 'REPLACE_WITH_POST_TEXT';
const imageUrl = 'REPLACE_WITH_IMAGE_URL_OR_LEAVE_EMPTY'; // public URL, Meta fetches it
const hashtags = ['#n8n', '#automation'];

// 2. The accounts (replace with your own IDs)
const pageId = 'REPLACE_WITH_FACEBOOK_PAGE_ID';
const instagramUserId = 'REPLACE_WITH_INSTAGRAM_BUSINESS_USER_ID';
const linkedInAuthorUrn = 'REPLACE_WITH_LINKEDIN_AUTHOR_URN'; // urn:li:person:xxx or urn:li:organization:xxx

const withTags = (body) => `${body} ${hashtags.join(' ')}`.trim();
const truncate = (s, max) => (s.length <= max ? s : s.slice(0, max - 1) + '...');

return {
  json: {
    // Content
    text,
    imageUrl,
    hasImage: Boolean(imageUrl),
    // Per-platform text (Instagram captions max 2200, X posts max 280)
    facebookText: withTags(text),
    instagramCaption: truncate(withTags(text), 2200),
    xText: truncate(withTags(text), 280),
    linkedInText: withTags(text),
    // Account IDs
    pageId,
    instagramUserId,
    linkedInAuthorUrn,
  },
};

// Reports what actually happened per platform. Nodes that never ran
// (e.g. the Instagram pair when there is no image) show as 'skipped'.
// A platform that failed is marked 'failed' with the error detail, but
// the workflow kept going thanks to onError: continueRegularOutput.
//
// Facebook runs two different nodes depending on the branch (photo vs
// text). Prefer the Post Photo result when it succeeded, otherwise fall
// back to Post Text, so the summary always reports the post that ran.

const get = (nodeName) => {
  try {
    const ref = $(nodeName);
    return ref ? ref.item.json : null;
  } catch (e) {
    return null;
  }
};

const summarize = (platform, nodeName) => {
  const data = get(nodeName);
  if (!data) return { platform, status: 'skipped' };
  if (data.error) {
    const detail = typeof data.error === 'string' ? data.error : JSON.stringify(data.error);
    return { platform, status: 'failed', detail };
  }
  return { platform, status: 'ok', id: data.id ?? null };
};

const photo = summarize('Facebook', 'Facebook: Post Photo');
const text = summarize('Facebook', 'Facebook: Post Text');
const facebook = photo.status === 'ok' ? photo : text.status !== 'skipped' ? text : photo;

return {
  json: {
    facebook,
    instagram: summarize('Instagram', 'Instagram: Publish Container'),
    x: summarize('X', 'X: Post Tweet'),
    linkedin: summarize('LinkedIn', 'LinkedIn: Post Update'),
  },
};
